SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.los, i.icustay_id, i.intime, i.outtime, i.length_of_stay, m.medication_complexity, m.medication_complexity_rank, m.medication_complexity_rank_percentile, m.medication_complexity_rank_quintile, m.medication_complexity_rank_quintile_label, m.medication_complexity_rank_quintile_label_short, m.medication_complexity_rank_quintile_label_long, m.medication_complexity_rank_quintile_label_short_with_percentile, m.medication_complexity_rank_quintile_label_long_with_percentile, m.medication_complexity_rank_quintile_label_short_with_percentile_and_rank, m.medication_complexity_rank_quintile_label_long_with_percentile_and_rank, m.medication_complexity_rank_quintile_label_short_with_percentile_and_rank_and_los, m.medication_complexity_rank_quintile_label_long_with_percentile_and_rank_and_los, m.medication_complexity_rank_quintile_label_short_with_percentile_and_rank_and_los_and_icu_stay_length, m.medication_complexity_rank_quintile_label_long_with_percentile_and_rank_and_los_and_icu_stay_length, m.medication_complexity_rank_quintile_label_short_with_percentile_and_rank_and_los_and_icu_stay_length_and_death_date, m.medication_complexity_rank_quintile_label_long_with_percentile_and_rank_and_los_and_icu_stay_length_and_death_date, m.medication_complexity_rank_quintile_label_short_with_percentile_and_rank_and_los_and_icu_stay_length_and_death_date_and_30_day_readmission_rate, m.medication_complexity_rank_quintile_label_long_with_percentile_and_rank_and_los_and_icu_stay_length_and_death_date_and_30_day_readmission_rate, m.medication_complexity_rank_quintile_label_short_with_percentile_and_rank_and_los_and_icu_stay_length_and_death_date_and_30_day_readmission_rate_and_risk_score, m.medication_complexity_rank_quintile_label_long_with_percentile_and_rank_and_los_and_icu_stay_length_and_death_date_and_30_day_readmission_rate_and_risk_score FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN medications m ON m.subject_id = p.subject_id AND m.hadm_id = a.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 42 AND p.anchor_year = 2017 AND p.anchor_year_group = '37-47' AND a.admittime <= '2017-01-01' AND a.dischtime >= '2017-12-31' AND (a.deathtime IS NOT NULL OR i.outtime >= a.dischtime + interval '72 hours') AND (a.deathtime IS NULL OR i.outtime < a.deathtime + interval '72 hours') AND (a.deathtime IS NULL OR (a.deathtime + interval '72 hours') <= i.;